#!/usr/bin/env python# -*- coding: utf-8 -*-"""Image data classes and mixins.This module provides the base classes and mixins for image data."""__all__ = [    "Image",]import cv2import numpy as npfrom mon.core.pathlib import Pathfrom ..base import Data, DataLoadMixinCV2_IMREAD_FLAGS = [    cv2.IMREAD_ANYCOLOR,    cv2.IMREAD_ANYDEPTH,    cv2.IMREAD_COLOR,    cv2.IMREAD_COLOR_BGR,    cv2.IMREAD_COLOR_RGB,    cv2.IMREAD_GRAYSCALE,    cv2.IMREAD_UNCHANGED,]# ==============================================================================# TYPE DEFINITIONS & PROTOCOLS (Interfaces)# ==============================================================================# --- Type Aliases ---# --- Structural Protocols ---# ==============================================================================# BASE CLASSES & MIXINS (Behaviors)# ==============================================================================# --- Structural Bases ---# --- Lifecycle Mixins ---# --- Compute Mixins ---# ==============================================================================# CONCRETE IMPLEMENTATIONS (The Concrete Classes)# ==============================================================================# --- Primary Data Types ---class Image(Data, DataLoadMixin):    """A basic class for managing a single image.    This class extends Data to handle a single image, which can be provided    either as an in-memory array or as a file path. It supports lazy loading,    optional caching, and provides properties to access image metadata.    Attributes:        _data (np.ndarray): An RGB image as a numpy.ndarray of shape (H, W, C)            with pixel values in the range [0, 255].        _path (Path): The image file path.        _root (Path): The root directory.        _shape (tuple[int, int, int]): The image shape.        _flags (int): OpenCV flag to read the image.        _cache (bool): Whether to cache the image in memory.    """        def __init__(        self,        data : np.ndarray | Path,        path : Path = None,        root : Path = None,        flags: int  = cv2.IMREAD_COLOR,        cache: bool = False,    ):        """Initialize the Image instance.        Args:            data: Either an RGB image as a numpy.ndarray of shape (H, W, C) with                pixel values in the range [0, 255], or an image file path.            path: Image file path. Defaults to None.            root: Root directory of the image (of a dataset). Defaults to None.            flags: OpenCV flag to read the image. Defaults to cv2.IMREAD_COLOR.            cache: If True, caches image in memory. Defaults to False.        Raises:            TypeError: If ``data`` is neither an array nor a valid image file path.            FileNotFoundError: If the provided image file path does not exist.            ValueError: If neither ``data`` nor a valid image ``path`` is provided,                or if the provided ``flag`` is not a valid OpenCV imread flag.        """        super().__init__(data=None)                # Validate data        shape = None        if isinstance(data, Path | str) and Path(data).is_image_file(exist=True):            path  = data            data  = None        elif isinstance(data, np.ndarray):            shape = data.shape        else:            raise TypeError(f"``data`` must be either a numpy.ndarray or a valid image file path, got {type(data)}.")                # Validate and set path        self._path = Path(path) if path is not None else None        self._root = Path(root) if root is not None else None        if data is None and self._path is not None:            if self._path.is_image_file(exist=True):                from . import io                shape = io.read_shape(path=path)            else:                raise FileNotFoundError(f"Image file not found: {path}.")                # Validate        if all(v is None for v in [data, self._path]):            raise ValueError("Either ``data`` or a valid image ``path`` must be provided.")                # Assign attributes        self._data  = data        self._shape = shape        self.flag   = flags        self.cache  = cache    #---- Magic Methods ---    def __len__(self) -> int:        """Return the logical length of the container.        For an Image this is always 1.        """        return 1        def __getitem__(self, idx: int = 0) -> np.ndarray:        """Return the image.        Args:            idx: Index to get the image. Defaults to 0.        Returns:            The image array.        """        return self.data        # --- Properties ---    @property    def data(self) -> np.ndarray:        """Return the underlying image array.        This property returns the image if it is already loaded in memory;        otherwise, it calls ``load()`` to load the image from disk.        Returns:            An image of shape (H, W, C) with pixel values in the range [0, 255].        """        return self._data if self._data is not None else self.load()        @property    def shape(self) -> tuple[int, int, int]:        """Return the original shape of the image as (H, W, C).        Returns:            The original shape of the image.        """        return self._shape        @property    def imgsz(self) -> tuple[int, int]:        """Return the image size as (H, W).        Returns:            The image size.        """        return self.shape[0], self.shape[1]        @property    def path(self) -> Path:        """Return the image file path.        Returns:            The image file path.        """        return self._path        @property    def root(self) -> Path:        """Return the root directory of the image (dataset root).        Returns:            The root directory of the image.        """        return self._root        @property    def flag(self) -> int:        """Return the OpenCV flag used to read the image."""        return self._flags        @flag.setter    def flag(self, flag: int):        """Set the OpenCV flag used to read the image.        Raises:            ValueError: If the provided flag is not a valid OpenCV imread flag.        """        if flag not in CV2_IMREAD_FLAGS:            raise ValueError(f"``flag`` must be one of {CV2_IMREAD_FLAGS}, got {flag}.")        self._flags = flag        @property    def cache(self) -> bool:        """Return whether image caching is enabled.        Returns:            True if caching is enabled, False otherwise.        """        return self._cache        @cache.setter    def cache(self, cache: bool):        """Enable or disable image caching.        Args:            cache: If True, enables caching of the image in memory. If False,                the image will be cleared if a valid image ``path`` is provided.        """        self._cache = bool(cache)        self.clear()        @property    def meta(self) -> dict:        """Return metadata about the image.        Returns:            A mapping with keys such as path, root, shape, imgsz and a file hash.        """        return {            "path" : self.path,            "root" : self.root,            "shape": self.shape,            "imgsz": self.imgsz,            "hash" : self.path.stat().st_size if isinstance(self.path, Path) else None,        }        # --- Data Loading ---    def load(self, reload: bool = False) -> np.ndarray:        """Load an image from disk to memory.        Args:            reload: If True, force reloading even if data is already in memory.        Returns:            An image of shape (H, W, C) with pixel values in the range [0, 255].        """        # Return the image if it is already loaded        if self._data is not None and not reload:            return self._data                # Load the image from disk        from .io import read        image = read(self.path, self._flags)                # Update the original shape of the image        if self._shape != image.shape:            self._shape = image.shape                # Cache the image if needed        if self.cache:            self._data = image        else:            self.clear()                    return image        def clear(self):        """Clear the cached image from memory when caching is disabled.        If caching is disabled and a valid image path exists, the in-memory        image is dropped so it can be reloaded when needed.        """        if (            not self.cache            and self.path is not None            and self.path.is_image_file(exist=True)        ):                self._data = None